def fibonacci(n):
    # Return 0 for non‑positive indices
    if n <= 0:
        return 0
    # First two Fibonacci numbers
    a, b = 0, 1
    # Iterate to compute the nth number
    for _ in range(1, n):
        a, b = b, a + b  # shift forward
    return b  # 'b' holds the nth Fibonacci value

